          ...(Array.isArray(verification.relatedFiles) ? { relatedFiles: verification.relatedFiles.map(f => ({ name: String(f.name), target: f.target === 'mobile' ? 'mobile' : 'desktop', text: String(f.text ?? ''), fields: (Array.isArray(f.fields) ? f.fields : []).slice(0, 200).map(String) })) } : {}),
