      PRODUCT_NOT_ENTITLED: 'PRODUCT_NOT_ENTITLED', FEATURE_NOT_ENTITLED: 'FEATURE_NOT_ENTITLED', FEATURE_NOT_IMPLEMENTED: 'FEATURE_NOT_IMPLEMENTED',
